_PLANNING_GUIDANCE = """\
## Planning

For work that takes several distinct steps, call `{plan_tool_name}` before you
start, then again as each step's status changes. The checklist is shown to
the user — it is how they see progress on a long turn. Each call replaces
the whole plan, so always send the complete list of items with their
current statuses.

Plan when the request:
- Touches more than one file ({multi_file_hint})
- Requires a validate/train cycle you intend to iterate on
- Names two or more deliverables ("add a returns skill and tests for it")
- Needs investigation before you know the fix ("the bot doesn't respond
  when...") — plan the diagnosis, then re-plan once you know the cause

Do NOT plan for:
- Questions about Rasa, CALM, or the user's project — including ones that
  need several read or search calls to answer. Reading is not multi-step
  work.
- Single-file edits ({single_file_hint})
- Anything you can finish in one write plus the standard validate/train

If you are unsure, plan. A checklist on a 2-step task is mild noise; a
dropped step on a 6-step task is a broken assistant the user has to debug.

Rules:
- Exactly one item in_progress at a time.
- Mark an item completed only when it actually succeeded. If validation
  fails, the item stays in_progress — add an item for the fix.
- Never re-send a plan identical to one you already sent. If a step has
  failed twice, stop and report what is blocking you instead of retrying.\
"""


_BRANCHING_GUIDANCE = """\
## Branches

You are working on the branch `{branch}`. When you create a branch, create it
before you edit any file.

- On `main`: before your first file edit, call `{branch_tool_name}` with a short
  kebab-case name describing the change (for example `add-returns-flow`, no ids
  or dates), then make your edits there. Skip this only when the user explicitly
  asks you to work on `main` directly; then edit `main` in place.
- On any other branch: edit in place, unless the user asks for a new branch.\
"""


_SKILLS_GUIDANCE = """\
## Copilot skills

Copilot skills are instructions for you, which you load with
`{load_skill_tool_name}`. They are not the skills in the user's project.

- Before you start a task that a skill's description covers, load that skill.
- Skills you loaded for an earlier user message are gone. Load a skill again
  whenever you need it.
- When a loaded skill has an `## Overrides` section, that section takes
  precedence over these instructions for that task.
- When a loaded skill points to a reference file, read it with
  `{load_reference_tool_name}`.\
"""


# The planning block is engine-neutral apart from the two examples that name
# project primitives, so it is parameterized rather than forked.
_CALM_V1_PLANNING_HINTS = {
    "multi_file_hint": (
        "a new flow almost always means the flow file AND domain changes, "
        'slots and responses, so most "add a flow" requests qualify'
    ),
    "single_file_hint": '"change utter_greet\'s text", "rename this slot"',
}
_MANTLE_PLANNING_HINTS = {
    "multi_file_hint": (
        "a new skill usually means `skills/<id>/skill.md` plus `memory.yml` "
        'and `responses.yml` edits, so most "add a skill" requests qualify'
    ),
    "single_file_hint": ('"change utter_greet\'s text", "rename a memory entry"'),
}


def branching_guidance(branch: str) -> str:
    """Return the prompt section for a run that may branch, on *branch*."""
    return _BRANCHING_GUIDANCE.format(
        branch=branch, branch_tool_name=TOOL_CREATE_BRANCH
    )


def skills_guidance() -> str:
    """Return the prompt section for a run that offers Copilot skills."""
    return _SKILLS_GUIDANCE.format(
        load_skill_tool_name=TOOL_LOAD_CAPABILITY,
        load_reference_tool_name=TOOL_LOAD_SKILL_REFERENCE,
    )


def load_system_prompt(engine: str = DEFAULT_ENGINE_VERSION) -> str:
    """Return the system prompt for the Copilot v2 agent on *engine*.

    Args:
        engine: Engine version the prompt is for, either
            ``CALM_ENGINE_VERSION`` or ``MANTLE_ENGINE_VERSION``. Anything
            else falls back to the CALM v1 prompt, so an unrecognized value can
            never leave a run without a system prompt.

    Returns:
        The engine's system prompt with the planning guidance appended.
    """
    is_mantle = engine == MANTLE_ENGINE_VERSION
    base = MANTLE_SYSTEM_PROMPT if is_mantle else V2_SYSTEM_PROMPT
    hints = _MANTLE_PLANNING_HINTS if is_mantle else _CALM_V1_PLANNING_HINTS
    planning = _PLANNING_GUIDANCE.format(plan_tool_name=PLAN_TOOL_NAME, **hints)
    return f"{base}\n\n{planning}"


def system_prompt_for_project(project_path: str | None) -> str:
    """Return the system prompt matching the project layout at *project_path*.

    Engine dispatch is per run, not per process: the agent is built once while
    the project directory arrives with each request. A missing path, or a path
    that cannot be inspected, yields the CALM v1 prompt, which is the
    pre-Mantle behavior.
    """
    return load_system_prompt(_engine_for_project(project_path))


def project_uses_mantle_layout(project_path: str | None) -> bool:
    """Return whether *project_path* has the Mantle (CALM v2) layout.

    A missing path, or a path that cannot be inspected, resolves to ``False``
    (CALM v1), the same fallback `_engine_for_project` uses to pick a prompt.
    """
    if project_path is None:
        return False
    try:
        return has_mantle_project_layout(Path(project_path))
    except OSError as exc:
        # A caller must always get an answer; an unreadable project directory
        # is not a reason to fail the turn.
        structlogger.warning(
            "copilot_v2.prompt.engine_detection_failed",
            error_type=type(exc).__name__,
        )
        return False


def _engine_for_project(project_path: str | None) -> str:
    """Resolve the engine version from a project directory, defaulting to v1."""
    return (
        MANTLE_ENGINE_VERSION
        if project_uses_mantle_layout(project_path)
        else CALM_ENGINE_VERSION
    )
